BEGIN SELECT RAISE(ABORT,'Lead lifecycle events are immutable'); END;
CREATE TRIGGER india_lead_intelligence_events_immutable_update BEFORE UPDATE ON india_lead_intelligence_events
BEGIN SELECT RAISE(ABORT,'Lead lifecycle events are immutable'); END;
CREATE TRIGGER india_lead_nurture_finish_on_qualification AFTER UPDATE OF status ON india_marketing_leads
WHEN NEW.status IN ('qualified','converted') AND OLD.status!=NEW.status
BEGIN
 UPDATE india_lead_nurture_plans SET state='completed',version=version+1,updated_by=NEW.updated_by,updated_at=CURRENT_TIMESTAMP
 WHERE lead_id=NEW.id AND tenant_id=NEW.tenant_id AND state IN ('active','paused');
END;
CREATE TRIGGER india_lead_reactivated_sla AFTER UPDATE OF status ON india_marketing_leads
WHEN OLD.status='disqualified' AND NEW.status IN ('new','assigned')
BEGIN
 INSERT INTO india_lead_sla_history(id,tenant_id,lead_id,snapshot_json)
 SELECT lower(hex(randomblob(16))),tenant_id,lead_id,json_object('owner_email',owner_email,'assigned_at',assigned_at,'response_due_at',response_due_at,'first_response_at',first_response_at,'baseline',baseline)
 FROM india_sales_lead_sla WHERE tenant_id=NEW.tenant_id AND lead_id=NEW.id;
 UPDATE india_sales_lead_sla SET owner_email=NEW.assigned_sales_email,first_response_at=NULL,baseline='new',assigned_at=strftime('%Y-%m-%dT%H:%M:%SZ','now'),
 response_due_at=strftime('%Y-%m-%dT%H:%M:%SZ','now',printf('+%d minutes',coalesce((SELECT lead_response_minutes FROM india_sales_activity_policy WHERE tenant_id=NEW.tenant_id),120)))
 WHERE tenant_id=NEW.tenant_id AND lead_id=NEW.id;
END;
CREATE TRIGGER india_lead_sla_history_delete BEFORE DELETE ON india_lead_sla_history
BEGIN SELECT RAISE(ABORT,'SLA_HISTORY_IMMUTABLE'); END;
CREATE TRIGGER india_lead_sla_history_update BEFORE UPDATE ON india_lead_sla_history
BEGIN SELECT RAISE(ABORT,'SLA_HISTORY_IMMUTABLE'); END;
CREATE TRIGGER india_lead_sla_new AFTER INSERT ON india_marketing_leads
BEGIN
 INSERT OR IGNORE INTO india_sales_lead_sla(tenant_id,lead_id,owner_email,assigned_at,response_due_at)
 VALUES(NEW.tenant_id,NEW.id,NEW.assigned_sales_email,strftime('%Y-%m-%dT%H:%M:%SZ','now'),
 strftime('%Y-%m-%dT%H:%M:%SZ','now',printf('+%d minutes',coalesce((SELECT lead_response_minutes FROM india_sales_activity_policy WHERE tenant_id=NEW.tenant_id),120))));
END;
CREATE TRIGGER india_lead_sla_reassigned AFTER UPDATE OF assigned_sales_email ON india_marketing_leads
WHEN NEW.assigned_sales_email<>OLD.assigned_sales_email
BEGIN
 UPDATE india_sales_lead_sla SET owner_email=NEW.assigned_sales_email,
 assigned_at=CASE WHEN first_response_at IS NULL THEN strftime('%Y-%m-%dT%H:%M:%SZ','now') ELSE assigned_at END,
 response_due_at=CASE WHEN first_response_at IS NULL THEN strftime('%Y-%m-%dT%H:%M:%SZ','now',printf('+%d minutes',coalesce((SELECT lead_response_minutes FROM india_sales_activity_policy WHERE tenant_id=NEW.tenant_id),120))) ELSE response_due_at END
 WHERE tenant_id=NEW.tenant_id AND lead_id=NEW.id;
END;
