 AND e.tenant_id=NEW.tenant_id AND e.opportunity_id=NEW.opportunity_id AND e.direction='inbound' AND (e.release_id IS NULL OR e.release_id=NEW.release_id))
BEGIN SELECT RAISE(ABORT,'FLOW_CONFLICT: email must belong to the same opportunity and release'); END;
CREATE TRIGGER india_number_no_delete BEFORE DELETE ON india_number_reservations BEGIN SELECT RAISE(ABORT,'NUMBER_IMMUTABLE'); END;
CREATE TRIGGER india_number_no_update BEFORE UPDATE ON india_number_reservations BEGIN SELECT RAISE(ABORT,'NUMBER_IMMUTABLE'); END;
CREATE TRIGGER india_operations_events_no_delete BEFORE DELETE ON india_operations_events BEGIN SELECT RAISE(ABORT,'OPERATIONS_AUDIT_IMMUTABLE'); END;
CREATE TRIGGER india_operations_events_no_update BEFORE UPDATE ON india_operations_events BEGIN SELECT RAISE(ABORT,'OPERATIONS_AUDIT_IMMUTABLE'); END;
CREATE TRIGGER india_opp_relation_frozen BEFORE UPDATE ON india_opportunity_relations BEGIN SELECT RAISE(ABORT,'DELIVERY_CONFLICT: immutable opportunity relationship'); END;
CREATE TRIGGER india_opportunity_relations_no_delete BEFORE DELETE ON india_opportunity_relations BEGIN SELECT RAISE(ABORT,'DELIVERY_CONFLICT: retain lifecycle history'); END;
CREATE TRIGGER india_org_change_flow BEFORE UPDATE ON india_org_change_requests
WHEN NEW.tenant_id IS NOT OLD.tenant_id OR NEW.id IS NOT OLD.id OR NEW.op IS NOT OLD.op OR NEW.payload_json IS NOT OLD.payload_json
 OR NEW.effective_date IS NOT OLD.effective_date OR NEW.maker IS NOT OLD.maker
 OR EXISTS(SELECT 1 FROM json_each(NEW.approvals_json) a WHERE lower(json_extract(a.value,'$.by'))=lower(OLD.maker))
 OR NOT ((OLD.status='pending' AND NEW.status IN ('pending','approved','rejected')) OR (OLD.status='approved' AND NEW.status='applied'))
BEGIN SELECT RAISE(ABORT,'ORG_CHANGE_INVALID'); END;
CREATE TRIGGER india_org_change_no_delete BEFORE DELETE ON india_org_change_requests BEGIN SELECT RAISE(ABORT,'ORG_CHANGE_INVALID'); END;
CREATE TRIGGER india_org_unit_legacy_map_immutable BEFORE UPDATE ON india_org_unit_legacy_map
WHEN OLD.status!='pending' OR NEW.org_unit_id IS NOT OLD.org_unit_id OR NEW.legal_entity_id IS NOT OLD.legal_entity_id OR NEW.maker IS NOT OLD.maker
BEGIN SELECT RAISE(ABORT,'LEGACY_MAP_IMMUTABLE'); END;
CREATE TRIGGER india_org_unit_legacy_map_target BEFORE INSERT ON india_org_unit_legacy_map
WHEN NOT EXISTS(SELECT 1 FROM india_org_units_v u WHERE u.tenant_id=NEW.tenant_id AND u.id=NEW.org_unit_id AND u.valid_to IS NULL AND u.status='active')
 OR NOT EXISTS(SELECT 1 FROM india_org_units_v u WHERE u.tenant_id=NEW.tenant_id AND u.id=NEW.legal_entity_id AND u.type='LEGAL_ENTITY' AND u.valid_to IS NULL)
BEGIN SELECT RAISE(ABORT,'LEGACY_MAP_TARGET_INVALID'); END;
CREATE TRIGGER india_org_units_v_history BEFORE UPDATE ON india_org_units_v
WHEN OLD.valid_to IS NOT NULL OR NEW.valid_to IS NULL OR NEW.tenant_id IS NOT OLD.tenant_id OR NEW.id IS NOT OLD.id OR NEW.version IS NOT OLD.version
 OR NEW.code IS NOT OLD.code OR NEW.name IS NOT OLD.name OR NEW.type IS NOT OLD.type OR NEW.parent_id IS NOT OLD.parent_id
 OR NEW.legal_entity_id IS NOT OLD.legal_entity_id OR NEW.profit_center IS NOT OLD.profit_center OR NEW.valid_from IS NOT OLD.valid_from
BEGIN SELECT RAISE(ABORT,'ORG_HISTORY_IMMUTABLE'); END;
CREATE TRIGGER india_org_units_v_no_delete BEFORE DELETE ON india_org_units_v BEGIN SELECT RAISE(ABORT,'ORG_HISTORY_IMMUTABLE'); END;
CREATE TRIGGER india_org_units_v_parent BEFORE INSERT ON india_org_units_v
WHEN NEW.parent_id IS NOT NULL AND NOT EXISTS(
 SELECT 1 FROM india_org_units_v p JOIN india_org_unit_types t ON t.code=NEW.type
 WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.parent_id AND p.status='active' AND p.valid_from<=NEW.valid_from AND (p.valid_to IS NULL OR p.valid_to>NEW.valid_from)
 AND EXISTS(SELECT 1 FROM json_each(t.allowed_parent_types_json) a WHERE a.value=p.type))
BEGIN SELECT RAISE(ABORT,'ORG_PARENT_TYPE_INVALID'); END;
CREATE TRIGGER india_org_units_v_profit BEFORE INSERT ON india_org_units_v
WHEN NEW.profit_center=1 AND NOT EXISTS(SELECT 1 FROM india_org_unit_types t WHERE t.code=NEW.type AND t.can_be_profit_center=1)
BEGIN SELECT RAISE(ABORT,'ORG_PROFIT_CENTER_NOT_ALLOWED'); END;
CREATE TRIGGER india_outbox_invoice_approved AFTER UPDATE OF status ON india_billing_invoices
WHEN OLD.status='draft' AND NEW.status='approved'
BEGIN
 INSERT INTO india_accounting_events(tenant_id,id,event_type,legal_entity_id,period,occurred_on,currency,amounts_json,dimensions_json,source_type,source_id,idempotency_key)
 SELECT NEW.tenant_id,'EVT-INV-'||NEW.id,'INVOICE_ON_ACCEPTANCE',m.legal_entity_id,substr(NEW.issue_date,1,7),NEW.issue_date,'IDR',
  json_object('gross',NEW.amount_cents+NEW.vat_cents,'net',NEW.amount_cents,'ppn',NEW.vat_cents),
  json_object('customer',p.customer_id,'project',p.id,'business_line',CASE p.service_family WHEN 'Cybersecurity Governance' THEN 'GOVERNANCE' WHEN 'GRC' THEN 'GOVERNANCE' WHEN 'Cybersecurity Technology' THEN 'TECH_TRADING' WHEN 'TECHNOLOGY' THEN 'TECH_TRADING' ELSE 'CYBERSECURITY' END,'invoice_number',NEW.number),
  'billing_invoice',NEW.id,'billing_invoice:'||NEW.id
 FROM india_delivery_projects p
 JOIN india_erp_project_scopes s ON s.tenant_id=p.tenant_id AND s.project_id=p.id AND s.status='approved'
 JOIN india_org_unit_legacy_map m ON m.tenant_id=s.tenant_id AND m.legacy_unit_id=s.legal_entity_id AND m.status='approved'
 WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.project_id;
END;
CREATE TRIGGER india_outbox_payment_approved AFTER UPDATE OF status ON india_billing_payments
WHEN OLD.status='draft' AND NEW.status='approved'
BEGIN
 INSERT INTO india_accounting_events(tenant_id,id,event_type,legal_entity_id,period,occurred_on,currency,amounts_json,dimensions_json,source_type,source_id,idempotency_key)
 SELECT NEW.tenant_id,'EVT-PAY-'||NEW.id,CASE WHEN NEW.amount_cents>0 THEN 'CASH_RECEIVED' ELSE 'CASH_REVERSED' END,m.legal_entity_id,substr(NEW.payment_date,1,7),NEW.payment_date,'IDR',
  CASE WHEN NEW.amount_cents>0 THEN json_object('cash',NEW.amount_cents,'pph23',0,'settled',NEW.amount_cents) ELSE json_object('amount',-NEW.amount_cents) END,
  json_object('customer',p.customer_id,'project',p.id,'business_line',CASE p.service_family WHEN 'Cybersecurity Governance' THEN 'GOVERNANCE' WHEN 'GRC' THEN 'GOVERNANCE' WHEN 'Cybersecurity Technology' THEN 'TECH_TRADING' WHEN 'TECHNOLOGY' THEN 'TECH_TRADING' ELSE 'CYBERSECURITY' END,'bank_reference',NEW.reference),
  'billing_payment',NEW.id,'billing_payment:'||NEW.id
 FROM india_billing_invoices i JOIN india_delivery_projects p ON p.tenant_id=i.tenant_id AND p.id=i.project_id
 JOIN india_erp_project_scopes s ON s.tenant_id=p.tenant_id AND s.project_id=p.id AND s.status='approved'
 JOIN india_org_unit_legacy_map m ON m.tenant_id=s.tenant_id AND m.legacy_unit_id=s.legal_entity_id AND m.status='approved'
 WHERE i.tenant_id=NEW.tenant_id AND i.id=NEW.invoice_id;
END;
CREATE TRIGGER india_outbox_payroll_approved AFTER UPDATE OF status ON india_payroll_runs
WHEN OLD.status='calculated' AND NEW.status='approved'
BEGIN
 INSERT INTO india_accounting_events(tenant_id,id,event_type,legal_entity_id,period,occurred_on,currency,amounts_json,dimensions_json,source_type,source_id,idempotency_key)
 VALUES(NEW.tenant_id,'EVT-PAYROLL-'||NEW.id,'PAYROLL_POSTED',NEW.legal_entity_id,NEW.period,date(NEW.period||'-01','+1 month','-1 day'),'IDR',
  json_object('gross_salary',NEW.gross_cents,'bpjs_employer',NEW.bpjs_employer_cents,'net_pay',NEW.net_cents,'pph21',NEW.pph21_cents,'bpjs_total',NEW.bpjs_employer_cents+NEW.bpjs_employee_cents),
  json_object('cost_center','PAYROLL-'||NEW.period,'payroll_run',NEW.id),'payroll_run',NEW.id,'payroll_run:'||NEW.id);
END;
CREATE TRIGGER india_partner_no_delete BEFORE DELETE ON india_partner_records BEGIN SELECT RAISE(ABORT,'PARTNER_IMMUTABLE'); END;
CREATE TRIGGER india_partner_snapshot_no_update BEFORE UPDATE ON india_partner_records
WHEN NEW.tenant_id!=OLD.tenant_id OR NEW.kind!=OLD.kind OR NEW.vendor_id!=OLD.vendor_id OR NEW.opportunity_id IS NOT OLD.opportunity_id
 OR NEW.offer_id IS NOT OLD.offer_id OR NEW.document_id IS NOT OLD.document_id OR NEW.title!=OLD.title OR NEW.created_by!=OLD.created_by
 OR NEW.version!=OLD.version+1
 OR (NEW.data_json!=OLD.data_json AND NOT(OLD.kind='purchase' AND OLD.status='ordered' AND NEW.status IN ('ordered','received')
 AND json_remove(NEW.data_json,'$.received_quantity','$.received_date')=json_remove(OLD.data_json,'$.received_quantity','$.received_date')
 AND json_extract(NEW.data_json,'$.received_quantity')>json_extract(OLD.data_json,'$.received_quantity')
 AND json_extract(NEW.data_json,'$.received_quantity')<=json_extract(OLD.data_json,'$.quantity')))
BEGIN SELECT RAISE(ABORT,'PARTNER_IMMUTABLE'); END;
CREATE TRIGGER india_payment_approve BEFORE UPDATE OF status ON india_billing_payments WHEN NEW.status='approved' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM india_billing_invoices i WHERE i.tenant_id=NEW.tenant_id AND i.id=NEW.invoice_id AND i.status='approved' AND NEW.payment_date>=i.issue_date
 AND (SELECT coalesce(sum(p.amount_cents),0) FROM india_billing_payments p WHERE p.invoice_id=i.id AND p.status='approved')+NEW.amount_cents BETWEEN 0 AND i.amount_cents+i.vat_cents)
 THEN RAISE(ABORT,'DELIVERY_CONFLICT: payment exceeds outstanding') END;
 SELECT CASE WHEN NEW.reversal_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM india_billing_payments p WHERE p.id=NEW.reversal_of AND p.invoice_id=NEW.invoice_id AND p.tenant_id=NEW.tenant_id AND p.status='approved' AND p.reversal_of IS NULL AND p.amount_cents=-NEW.amount_cents AND NEW.payment_date>=p.payment_date)
 THEN RAISE(ABORT,'DELIVERY_CONFLICT: exact approved reversal required') END;
END;
CREATE TRIGGER india_payroll_contribution_rates_history BEFORE UPDATE ON india_payroll_contribution_rates WHEN OLD.effective_to IS NOT NULL OR NEW.effective_to IS NULL OR NEW.rate IS NOT OLD.rate BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_payroll_contribution_rates_no_delete BEFORE DELETE ON india_payroll_contribution_rates BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_payroll_jkk_classes_history BEFORE UPDATE ON india_payroll_jkk_classes WHEN OLD.effective_to IS NOT NULL OR NEW.effective_to IS NULL OR NEW.rate IS NOT OLD.rate BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_payroll_jkk_classes_no_delete BEFORE DELETE ON india_payroll_jkk_classes BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_payroll_lines_immutable BEFORE UPDATE ON india_payroll_lines BEGIN SELECT RAISE(ABORT,'PAYROLL_LINE_IMMUTABLE'); END;
CREATE TRIGGER india_payroll_lines_lock BEFORE INSERT ON india_payroll_lines
WHEN NOT EXISTS(SELECT 1 FROM india_payroll_runs r WHERE r.tenant_id=NEW.tenant_id AND r.id=NEW.run_id AND r.status='draft')
BEGIN SELECT RAISE(ABORT,'PAYROLL_RUN_LOCKED'); END;
CREATE TRIGGER india_payroll_lines_no_delete BEFORE DELETE ON india_payroll_lines
WHEN NOT EXISTS(SELECT 1 FROM india_payroll_runs r WHERE r.tenant_id=OLD.tenant_id AND r.id=OLD.run_id AND r.status='draft')
BEGIN SELECT RAISE(ABORT,'PAYROLL_RUN_LOCKED'); END;
CREATE TRIGGER india_payroll_runs_flow BEFORE UPDATE ON india_payroll_runs
WHEN NEW.version!=OLD.version+1 OR NEW.tenant_id IS NOT OLD.tenant_id OR NEW.id IS NOT OLD.id OR NEW.legal_entity_id IS NOT OLD.legal_entity_id
 OR NEW.period IS NOT OLD.period OR NEW.maker IS NOT OLD.maker
 OR NOT ((OLD.status='draft' AND NEW.status IN ('draft','calculated'))
      OR (OLD.status='calculated' AND NEW.status IN ('draft','approved','rejected'))
      OR (OLD.status='approved' AND NEW.status='posted' AND NEW.gross_cents=OLD.gross_cents AND NEW.pph21_cents=OLD.pph21_cents AND NEW.net_cents=OLD.net_cents))
 OR (OLD.status IN ('approved','posted') AND (NEW.gross_cents!=OLD.gross_cents OR NEW.pph21_cents!=OLD.pph21_cents OR NEW.bpjs_employer_cents!=OLD.bpjs_employer_cents))
BEGIN SELECT RAISE(ABORT,'PAYROLL_RUN_TRANSITION_INVALID'); END;
CREATE TRIGGER india_payroll_runs_no_delete BEFORE DELETE ON india_payroll_runs BEGIN SELECT RAISE(ABORT,'PAYROLL_RUN_IMMUTABLE'); END;
CREATE TRIGGER india_po_no_delete BEFORE DELETE ON india_purchase_orders BEGIN SELECT RAISE(ABORT,'PO_IMMUTABLE'); END;
CREATE TRIGGER india_po_review BEFORE UPDATE ON india_purchase_orders
BEGIN
 SELECT CASE WHEN OLD.status!='draft' OR NEW.status NOT IN ('approved','rejected') OR NEW.version!=OLD.version+1
 OR NEW.id IS NOT OLD.id OR NEW.tenant_id IS NOT OLD.tenant_id OR NEW.vendor_id IS NOT OLD.vendor_id
 OR NEW.offer_id IS NOT OLD.offer_id OR NEW.opportunity_id IS NOT OLD.opportunity_id
 OR NEW.po_number IS NOT OLD.po_number OR NEW.qty IS NOT OLD.qty OR NEW.unit_price_cents IS NOT OLD.unit_price_cents
 OR NEW.created_by IS NOT OLD.created_by OR lower(NEW.reviewed_by)=lower(OLD.created_by)
 THEN RAISE(ABORT,'PO_IMMUTABLE') END;
END;
CREATE TRIGGER india_po_source BEFORE INSERT ON india_purchase_orders
WHEN NOT EXISTS(SELECT 1 FROM india_vendor_offers o JOIN india_vendors v
 ON v.tenant_id=o.tenant_id AND v.id=o.vendor_id
 WHERE o.tenant_id=NEW.tenant_id AND o.id=NEW.offer_id AND o.vendor_id=NEW.vendor_id AND o.opportunity_id=NEW.opportunity_id
 AND o.status='validated' AND v.status='validated' AND o.valid_until>=date('now') AND v.valid_until>=date('now')
 AND o.quantity>=NEW.qty AND abs(o.unit_price_idr*100-NEW.unit_price_cents)<1)
BEGIN SELECT RAISE(ABORT,'PO_SOURCE_INVALID'); END;
CREATE TRIGGER india_policy_decisions_no_delete BEFORE DELETE ON india_policy_decisions BEGIN SELECT RAISE(ABORT,'POLICY_LOG_IMMUTABLE'); END;
CREATE TRIGGER india_policy_decisions_no_update BEFORE UPDATE ON india_policy_decisions BEGIN SELECT RAISE(ABORT,'POLICY_LOG_IMMUTABLE'); END;
CREATE TRIGGER india_posting_rules_immutable BEFORE UPDATE ON india_posting_rules
WHEN OLD.status!='pending' AND (NEW.rule_json IS NOT OLD.rule_json OR NEW.event_type IS NOT OLD.event_type OR NEW.effective_from IS NOT OLD.effective_from)
BEGIN SELECT RAISE(ABORT,'POSTING_RULE_IMMUTABLE'); END;
