BEGIN SELECT RAISE(ABORT,'TARGET_EVENT_IMMUTABLE'); END;
CREATE TRIGGER india_targets_events_immutable_update BEFORE UPDATE ON india_sales_target_events
BEGIN SELECT RAISE(ABORT,'TARGET_EVENT_IMMUTABLE'); END;
CREATE TRIGGER india_tax_progressive_brackets_history BEFORE UPDATE ON india_tax_progressive_brackets WHEN OLD.effective_to IS NOT NULL OR NEW.effective_to IS NULL OR NEW.rate IS NOT OLD.rate BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_tax_progressive_brackets_no_delete BEFORE DELETE ON india_tax_progressive_brackets BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_tax_ptkp_history BEFORE UPDATE ON india_tax_ptkp WHEN OLD.effective_to IS NOT NULL OR NEW.effective_to IS NULL OR NEW.annual_cents IS NOT OLD.annual_cents BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
