CREATE TRIGGER india_tender_checklist_history BEFORE UPDATE ON india_tender_checklist
BEGIN INSERT INTO india_tender_readiness_history(id,tenant_id,opportunity_id,entity_kind,entity_id,snapshot_json)
 VALUES(lower(hex(randomblob(16))),OLD.tenant_id,OLD.opportunity_id,'checklist',OLD.id,
 json_object('item_code',OLD.item_code,'category',OLD.category,'label',OLD.label,'mandatory',OLD.mandatory,
 'document_name',OLD.document_name,'evidence_reference',OLD.evidence_reference,'evidence_sha256',OLD.evidence_sha256,
 'source_clause_id',OLD.source_clause_id,'due_at',OLD.due_at,'status',OLD.status,'version',OLD.version,
 'created_by',OLD.created_by,'checked_by',OLD.checked_by,'review_notes',OLD.review_notes)); END;
CREATE TRIGGER india_tender_deadline_history BEFORE UPDATE ON india_tender_deadlines
BEGIN INSERT INTO india_tender_readiness_history(id,tenant_id,opportunity_id,entity_kind,entity_id,snapshot_json)
 VALUES(lower(hex(randomblob(16))),OLD.tenant_id,OLD.opportunity_id,'deadline',OLD.id,
 json_object('milestone',OLD.milestone,'due_at',OLD.due_at,'status',OLD.status,'notes',OLD.notes,'version',OLD.version,
 'created_by',OLD.created_by,'reviewed_by',OLD.reviewed_by,'review_notes',OLD.review_notes)); END;
CREATE TRIGGER india_tender_matrix_gate BEFORE UPDATE OF stage ON india_sales_opportunities
WHEN NEW.stage!=OLD.stage AND NEW.stage IN ('commercial_review','quotation_sent','negotiation','pending_po','closed_won')
 AND (EXISTS(SELECT 1 FROM india_sales_bids b WHERE b.tenant_id=NEW.tenant_id AND b.opportunity_id=NEW.id AND b.channel!='direct')
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%tender%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%rfp%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%rfq%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%lpse%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%spse%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%pengadaan%')
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM india_sales_requirements r WHERE r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.id
 AND r.kind IN ('rks','kak','rfp','rfq') AND r.status='reviewed' AND r.compliance_status='compliant'
 AND EXISTS(SELECT 1 FROM india_tender_compliance_items c WHERE c.requirement_id=r.id AND c.mandatory=1)
 AND NOT EXISTS(SELECT 1 FROM india_tender_compliance_gaps c WHERE c.requirement_id=r.id AND c.mandatory=1 AND c.is_gap=1))
 THEN RAISE(ABORT,'COMPLIANCE_CONFLICT: reviewed clause matrix and current vendor validation required') END;
END;
CREATE TRIGGER india_tender_package_stage_gate BEFORE UPDATE OF stage ON india_sales_opportunities
WHEN NEW.stage!=OLD.stage AND NEW.stage IN ('commercial_review','quotation_sent','negotiation','pending_po','closed_won')
 AND (EXISTS(SELECT 1 FROM india_sales_bids b WHERE b.tenant_id=NEW.tenant_id AND b.opportunity_id=NEW.id AND b.channel!='direct')
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%tender%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%rfp%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%rfq%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%lpse%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%spse%'
 OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%pengadaan%')
BEGIN
 SELECT CASE WHEN NOT EXISTS(
 SELECT 1 FROM india_tender_deadlines t WHERE t.tenant_id=NEW.tenant_id AND t.opportunity_id=NEW.id
 AND t.milestone='submission' AND t.status='approved' AND datetime(t.due_at)>datetime('now')

 AND EXISTS(SELECT 1 FROM india_sales_bids b WHERE b.tenant_id=NEW.tenant_id AND b.opportunity_id=NEW.id AND b.bid_decision='go' AND b.decided_by IS NOT NULL)
 AND EXISTS(SELECT 1 FROM india_sales_requirements r WHERE r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.id AND r.kind IN ('rks','kak','rfp','rfq'))
 AND NOT EXISTS(SELECT 1 FROM india_sales_requirements r WHERE r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.id AND r.kind IN ('rks','kak','rfp','rfq')
 AND (r.status!='reviewed' OR r.compliance_status!='compliant' OR r.reviewed_by IS NULL OR length(r.file_reference)=0 OR length(r.source_content_hash)!=64
 OR NOT EXISTS(SELECT 1 FROM india_tender_compliance_items c WHERE c.requirement_id=r.id AND c.mandatory=1)
 OR EXISTS(SELECT 1 FROM india_tender_compliance_gaps c WHERE c.requirement_id=r.id AND c.mandatory=1 AND c.is_gap=1)))
 AND (SELECT count(DISTINCT category) FROM india_tender_checklist c WHERE c.tenant_id=NEW.tenant_id
 AND c.opportunity_id=NEW.id AND c.mandatory=1)=3
 AND NOT EXISTS(SELECT 1 FROM india_tender_checklist c WHERE c.tenant_id=NEW.tenant_id
 AND c.opportunity_id=NEW.id AND c.mandatory=1 AND
 (c.status!='ready' OR length(c.evidence_reference)<8 OR length(c.evidence_sha256)!=64
 OR c.checked_by IS NULL OR lower(c.checked_by)=lower(c.created_by)
 OR (c.due_at IS NOT NULL AND datetime(c.due_at)<datetime('now'))))
 ) THEN RAISE(ABORT,'READINESS_CONFLICT: submission deadline and mandatory bid package must be reviewed') END;
END;
CREATE TRIGGER india_tender_readiness_history_immutable_delete BEFORE DELETE ON india_tender_readiness_history
BEGIN SELECT RAISE(ABORT,'READINESS_HISTORY_IMMUTABLE'); END;
CREATE TRIGGER india_tender_readiness_history_immutable_update BEFORE UPDATE ON india_tender_readiness_history
BEGIN SELECT RAISE(ABORT,'READINESS_HISTORY_IMMUTABLE'); END;
CREATE TRIGGER india_tender_vault_clause_review BEFORE UPDATE OF status ON india_tender_compliance_items
WHEN NEW.status='reviewed' AND NEW.mandatory=1
 AND NOT EXISTS(
  SELECT 1 FROM india_tender_vault_originals v
  WHERE v.tenant_id=NEW.tenant_id AND v.opportunity_id=NEW.opportunity_id
   AND v.evidence_reference=NEW.evidence_reference AND v.sha256=NEW.evidence_sha256
 )
BEGIN SELECT RAISE(ABORT,'TENDER_VAULT_EVIDENCE: mandatory clause requires its stored original'); END;
CREATE TRIGGER india_tender_vault_item_review BEFORE UPDATE OF status ON india_tender_checklist
WHEN NEW.status='ready' AND NEW.mandatory=1
 AND NOT EXISTS(
  SELECT 1 FROM india_tender_vault_originals v
  WHERE v.tenant_id=NEW.tenant_id AND v.opportunity_id=NEW.opportunity_id
   AND v.evidence_reference=NEW.evidence_reference
   AND v.sha256=NEW.evidence_sha256 AND v.file_name=NEW.document_name
 )
BEGIN SELECT RAISE(ABORT,'TENDER_VAULT_EVIDENCE: mandatory checklist requires an uploaded original'); END;
CREATE TRIGGER india_tender_vault_requirement_review BEFORE UPDATE OF status ON india_sales_requirements
WHEN NEW.status='reviewed' AND NEW.compliance_status='compliant'
 AND NEW.kind IN ('rks','kak','rfp','rfq')
 AND NOT EXISTS(
  SELECT 1 FROM india_tender_vault_originals v
  WHERE v.tenant_id=NEW.tenant_id AND v.opportunity_id=NEW.opportunity_id
   AND v.evidence_reference=NEW.file_reference AND v.sha256=NEW.source_content_hash
   AND v.kind=CASE WHEN NEW.kind IN ('rks','kak') THEN NEW.kind ELSE 'supporting' END
 )
BEGIN SELECT RAISE(ABORT,'TENDER_VAULT_EVIDENCE: RKS/KAK source must exist in Document Vault'); END;
CREATE TRIGGER india_tender_vault_stage BEFORE UPDATE OF stage ON india_sales_opportunities
WHEN NEW.stage!=OLD.stage
 AND NEW.stage IN ('commercial_review','quotation_sent','negotiation','pending_po','closed_won')
 AND (EXISTS(SELECT 1 FROM india_sales_bids b WHERE b.tenant_id=NEW.tenant_id AND b.opportunity_id=NEW.id AND b.channel!='direct')
      OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%tender%'
      OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%rfp%'
      OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%rfq%'
      OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%lpse%'
      OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%spse%'
      OR lower(coalesce(json_extract(NEW.data_json,'$.procurement_process'),'')) LIKE '%pengadaan%')
 AND (
   EXISTS(SELECT 1 FROM india_tender_checklist c
          WHERE c.tenant_id=NEW.tenant_id AND c.opportunity_id=NEW.id AND c.mandatory=1
           AND NOT EXISTS(SELECT 1 FROM india_tender_vault_originals v
             WHERE v.tenant_id=c.tenant_id AND v.opportunity_id=c.opportunity_id
             AND v.evidence_reference=c.evidence_reference AND v.sha256=c.evidence_sha256 AND v.file_name=c.document_name))
   OR EXISTS(SELECT 1 FROM india_sales_requirements r
          WHERE r.tenant_id=NEW.tenant_id AND r.opportunity_id=NEW.id AND r.kind IN ('rks','kak','rfp','rfq')
           AND NOT EXISTS(SELECT 1 FROM india_tender_vault_originals v
             WHERE v.tenant_id=r.tenant_id AND v.opportunity_id=r.opportunity_id
             AND v.evidence_reference=r.file_reference AND v.sha256=r.source_content_hash
             AND v.kind=CASE WHEN r.kind IN ('rks','kak') THEN r.kind ELSE 'supporting' END))
   OR EXISTS(SELECT 1 FROM india_tender_compliance_items c
          WHERE c.tenant_id=NEW.tenant_id AND c.opportunity_id=NEW.id AND c.mandatory=1
           AND NOT EXISTS(SELECT 1 FROM india_tender_vault_originals v
             WHERE v.tenant_id=c.tenant_id AND v.opportunity_id=c.opportunity_id
             AND v.evidence_reference=c.evidence_reference AND v.sha256=c.evidence_sha256))
 )
BEGIN SELECT RAISE(ABORT,'TENDER_VAULT_EVIDENCE: tender originals are missing or mismatched'); END;
CREATE TRIGGER india_timesheet_capacity BEFORE INSERT ON india_project_timesheets
 BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM india_delivery_projects p
    JOIN india_resource_allocations a ON a.tenant_id=p.tenant_id AND a.opportunity_id=p.opportunity_id AND a.id=NEW.allocation_id
    JOIN india_resource_people r ON r.tenant_id=a.tenant_id AND r.id=a.person_id
    WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.project_id AND p.status='active'
      AND r.id=NEW.person_id AND r.active=1 AND a.status='active'
      AND substr(NEW.work_date,1,7)=a.allocation_month
      AND NEW.work_date BETWEEN p.start_date AND p.end_date
      AND lower(NEW.created_by)=lower(r.email)
      AND NEW.minutes+coalesce((SELECT sum(t.minutes) FROM india_project_timesheets t
          WHERE t.tenant_id=NEW.tenant_id AND t.person_id=NEW.person_id AND t.work_date=NEW.work_date AND t.status!='rejected'),0)<=480
      AND NEW.minutes+coalesce((SELECT sum(t.minutes) FROM india_project_timesheets t
          WHERE t.tenant_id=NEW.tenant_id AND t.allocation_id=NEW.allocation_id AND t.status!='rejected'),0)<=round(a.person_days*480)
  ) THEN RAISE(ABORT,'TIMESHEET_CAPACITY_CONFLICT') END;
 END;
CREATE TRIGGER india_timesheet_no_delete BEFORE DELETE ON india_project_timesheets
 BEGIN SELECT RAISE(ABORT,'TIMESHEET_IMMUTABLE'); END;
CREATE TRIGGER india_timesheet_review_capacity BEFORE UPDATE OF status ON india_project_timesheets WHEN NEW.status='approved'
 BEGIN
  SELECT CASE WHEN NOT EXISTS (
   SELECT 1 FROM india_resource_allocations a JOIN india_resource_people r ON r.id=a.person_id AND r.tenant_id=a.tenant_id
   WHERE a.id=NEW.allocation_id AND a.tenant_id=NEW.tenant_id AND a.status='active' AND r.active=1
    AND (SELECT coalesce(sum(t.minutes),0) FROM india_project_timesheets t WHERE t.tenant_id=NEW.tenant_id AND t.allocation_id=a.id AND t.status!='rejected')<=round(a.person_days*480)
  ) THEN RAISE(ABORT,'TIMESHEET_CAPACITY_CONFLICT') END;
 END;
CREATE TRIGGER india_timesheet_transition BEFORE UPDATE ON india_project_timesheets
 BEGIN
  SELECT CASE WHEN OLD.status!='submitted' OR NEW.status NOT IN ('approved','rejected')
   OR NEW.version!=OLD.version+1 OR NEW.id IS NOT OLD.id OR NEW.tenant_id IS NOT OLD.tenant_id
   OR NEW.project_id IS NOT OLD.project_id OR NEW.person_id IS NOT OLD.person_id
   OR NEW.allocation_id IS NOT OLD.allocation_id OR NEW.work_date IS NOT OLD.work_date
   OR NEW.minutes IS NOT OLD.minutes OR NEW.billable IS NOT OLD.billable
   OR NEW.cost_snapshot_cents IS NOT OLD.cost_snapshot_cents
   OR NEW.description IS NOT OLD.description OR NEW.created_by IS NOT OLD.created_by
   OR lower(NEW.reviewed_by)=lower(OLD.created_by)
   THEN RAISE(ABORT,'TIMESHEET_IMMUTABLE') END;
 END;
CREATE TRIGGER india_vendor_history BEFORE UPDATE ON india_vendors
BEGIN INSERT INTO india_procurement_history VALUES(lower(hex(randomblob(16))),OLD.tenant_id,'vendor',OLD.id,json_object('legal_name',OLD.legal_name,'registration_number',OLD.registration_number,'contact_email',OLD.contact_email,'capabilities',OLD.capabilities,'capacity_units',OLD.capacity_units,'capacity_unit',OLD.capacity_unit,'evidence_reference',OLD.evidence_reference,'evidence_sha256',OLD.evidence_sha256,'valid_until',OLD.valid_until,'version',OLD.version,'status',OLD.status,'created_by',OLD.created_by,'reviewed_by',OLD.reviewed_by,'review_notes',OLD.review_notes),CURRENT_TIMESTAMP); END;
